 const missing=Object.values(ruleRights).filter(right=>!hostActions(client,host.id).includes(right));
 const full=preview&&Object.keys(ruleRights).every(tool=>(client.approvals||[]).some(entry=>entry.rule.hostId===host.id&&entry.binding===preview.binding&&entry.rule.tool===tool&&(tool==='harbor_exec'?entry.rule.scope==='all-commands':['harbor_list_files','harbor_read_file','harbor_write_file'].includes(tool)?entry.rule.scope==='all-paths':true)));
