 {permittedHosts.length>0&&!visibleHosts.length&&<div className="mcp-empty" role="status"><h3>No matching hosts</h3><p>Try a different host name or address.</p><button type="button" className="button" onClick={()=>setSearch('')}>Clear search</button></div>}
