 useEffect(()=>{const opener=document.activeElement;review.current?.scrollIntoView({block:'nearest'});review.current?.querySelector('select')?.focus({preventScroll:true});return()=>{if(opener?.isConnected)opener.focus({preventScroll:true})}},[]);
