  harbor_connect:['Opens a connection',`Connects as ${request.target.username} on this server. SSH identity checks and authentication still apply. Later actions remain subject to this client’s permissions.`],
  harbor_disconnect:['Closes this connection','Disconnects this client’s selected SSH session. Other clients and your terminal tabs are unaffected.'],
  harbor_exec:['May change the server',`Runs the exact command below with this SSH account’s permissions. Commands can modify or delete data. Output is shared with ${request.client} and may be sent to its AI provider.`],
